// Generated by AI

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { api, geocode } from "@/services/api";

const place = { lat: -23.5886, lon: -48.0483, name: "Itapetininga" };
const location = { latitude: place.lat, longitude: place.lon };
const fetchMock = vi.fn<typeof fetch>();

beforeEach(() => {
  vi.stubEnv("VITE_API_BASE_URL", "https://nasa-challenge-nvrf.onrender.com");
  vi.stubGlobal("fetch", fetchMock);
});
afterEach(() => {
  vi.unstubAllEnvs();
  vi.unstubAllGlobals();
  fetchMock.mockReset();
});

describe("FastAPI client integration", () => {
  it("uses FastAPI coordinates and reads NASA POWER daily values", async () => {
    fetchMock.mockResolvedValue(
      Response.json({
        source: "NASA POWER",
        last_available_date: "2026-05-01",
        daily: [
          {
            date: "2026-05-01",
            temperature: 22,
            precipitation: 10,
            relative_humidity: 65,
            wind_speed: 3,
          },
        ],
      }),
    );

    const history = await api.history(place, 90);
    expect(fetchMock.mock.calls[0]?.[0]).toBe(
      "https://nasa-challenge-nvrf.onrender.com/api/v1/climate/history?latitude=-23.5886&longitude=-48.0483&days=90",
    );
    expect(history.days[0]).toMatchObject({ humidity: 65, wind: 3, precipitation: 10 });
    expect(history.reference_date).toBe("2026-05-01");
  });

  it("sends the full planting date and the typed culture for rotation", async () => {
    fetchMock.mockResolvedValue(Response.json({ strategies: [], limitations: [] }));
    await api.rotation({
      location: place,
      planting_date: "2026-11-25",
      previous_crop_name: "Feijão",
      priority: "soil_conservation",
      previous_planting_date: "2025-10-10",
    });

    expect(JSON.parse(String(fetchMock.mock.calls[0]?.[1]?.body))).toEqual({
      location,
      planting_month: 11,
      planting_year: 2026,
      planting_day: 25,
      previous_crop_name: "Feijão",
      objective: "soil_conservation",
      previous_planting_date: "2025-10-10",
    });
  });

  it("sends at most eight chat messages without UI metadata", async () => {
    const metadata = { answer: "663 meters", sources: [], kind: "observed" as const };
    fetchMock.mockResolvedValue(
      Response.json({
        status: "available",
        answer: metadata.answer,
        limitations: [],
        sources: [{ title: "NASA SRTM", url: "https://www.opentopodata.org/" }],
      }),
    );
    const answer = await api.chat({
      message: "What is the elevation?",
      location: place,
      history: Array.from({ length: 10 }, (_, i) => ({
        role: "assistant",
        content: String(i),
        metadata,
      })),
    });

    const request = fetchMock.mock.calls[0]?.[1];
    expect(new Headers(request?.headers).get("Accept-Language")).toBe("en");
    const body = JSON.parse(String(request?.body));
    expect(body.location).toEqual(location);
    expect(body.history).toHaveLength(8);
    expect(body.history[0]).toEqual({ role: "assistant", content: "2" });
    expect(answer).toMatchObject({ answer: "663 meters", sources: ["NASA SRTM"] });
  });

  it("finds municipalities by name without an external geocoder", async () => {
    const results = await geocode("Sao Paulo, SP");
    expect(results).toHaveLength(1);
    expect(results[0]?.name).toBe("São Paulo, SP");
    expect(fetchMock).not.toHaveBeenCalled();
  });

  it("falls back to direct Open-Meteo when backend returns provider_error for forecast and risks", async () => {
    const openMeteoPayload = {
      current: {
        time: "2026-11-15T17:15",
        temperature_2m: 23.2,
        relative_humidity_2m: 83,
        precipitation: 0.6,
        wind_speed_10m: 2.5,
        wind_gusts_10m: 23.4,
        soil_moisture_0_to_1cm: 0.42,
        soil_moisture_1_to_3cm: 0.42,
        soil_moisture_3_to_9cm: 0.42,
      },
      daily: {
        time: [
          "2026-11-15",
          "2026-11-16",
          "2026-11-17",
          "2026-11-18",
          "2026-11-19",
          "2026-11-20",
          "2026-11-21",
        ],
        temperature_2m_min: [18.1, 18.8, 18.0, 16.9, 19.8, 20.4, 20.8],
        temperature_2m_max: [36.5, 25.6, 27.6, 29.0, 29.8, 29.0, 30.3],
        temperature_2m_mean: [21.3, 21.2, 22.0, 22.8, 24.2, 24.0, 23.3],
        relative_humidity_2m_mean: [89, 87, 80, 82, 85, 88, 92],
        precipitation_sum: [27.8, 3.5, 0.0, 0.4, 1.5, 3.3, 6.0],
        precipitation_probability_max: [97, 87, 56, 74, 53, 62, 61],
        wind_speed_10m_max: [17.4, 20.9, 17.2, 9.3, 11.4, 13.8, 10.3],
        wind_gusts_10m_max: [37.4, 43.2, 35.6, 20.5, 30.6, 31.7, 28.4],
        et0_fao_evapotranspiration: [3.64, 3.98, 4.69, 5.46, 4.74, 4.35, 4.51],
      },
    };

    fetchMock
      .mockResolvedValueOnce(
        Response.json({
          status: "provider_error",
          source: "Open-Meteo",
          current: { reference_time: null },
          daily: [],
        }),
      )
      .mockResolvedValueOnce(Response.json(openMeteoPayload))
      .mockResolvedValueOnce(
        Response.json({
          status: "provider_error",
          period_start: null,
          period_end: null,
          indicators: [],
        }),
      );

    const forecast = await api.forecast(place);
    expect(forecast).toHaveLength(7);
    expect(forecast[0]).toMatchObject({
      date: "2026-11-15",
      temperature: 21.3,
      precipitation: 27.8,
      rain_probability: 97,
    });

    const risks = await api.risks(place, "sugarcane");
    expect(risks).toHaveLength(5);
    const heat = risks.find((r) => r.id === "heat");
    const deficit = risks.find((r) => r.id === "water_deficit");
    expect(heat?.level).toBe("High");
    expect(deficit?.level).toBe("Low");
    expect(deficit?.period).toBe("Nov 15, 2026 to Nov 21, 2026");
  });
});
